UPDATE /* delTargetReply */
       TB_REPLXX
   SET DELT_YSNO = #{yes}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE REPL_NUMB = #{replNumb}
   AND USER_NUMB = #{userNumb}
   AND DELT_YSNO = #{no}

