SELECT /* getTargetContentCount */
       CASE
           WHEN #{tagtType} = #{bookReport} THEN EXISTS (
               SELECT 1
                 FROM TM_REPORT P
                WHERE P.REPT_NUMB = #{tagtNumb}
                  AND P.USER_NUMB = #{userNumb}
           )
           WHEN #{tagtType} = #{reply} THEN EXISTS (
               SELECT 1
                 FROM TB_REPLXX R
                WHERE R.REPL_NUMB = #{tagtNumb}
                  AND R.USER_NUMB = #{userNumb}
                  AND R.DELT_YSNO = #{no}
           )
           WHEN #{tagtType} = #{club} THEN EXISTS (
               SELECT 1
                 FROM TM_CLUBXM C
                WHERE C.CLUB_NUMB = #{tagtNumb}
                  AND C.CLUB_CNTN IS NOT NULL
           )
           ELSE 0
       END
